import{j as e}from"./index-Cvn8XixQ.js";import{G as t}from"./GuidePageLayout-DjCFcGug.js";import"./PageBanner-C2RyqhZh.js";import"./Breadcrumbs-C1y9bcgc.js";import"./chevron-right-B7ezrMbL.js";import"./ServicePageLayout-DL5HiLt9.js";import"./button-W0vxHA79.js";function l(){return e.jsx(t,{"code-path":"src\\pages\\guides\\SenderIdRegistration.tsx:5:5",title:"Sender ID Registration in Kenya",subtitle:"Register an SMS Sender ID with CAK — the 2026 guide",description:"A sender ID is the name customers see as the 'from' field on an SMS (e.g. MobiWave). In Kenya, alphanumeric sender IDs are registered with the mobile networks under the Communications Authority of Kenya (CAK) framework. This guide covers who needs one, what documents you need, how long approval takes, and how MobiWave handles it for you at no extra admin fee.",breadcrumbLabel:"Sender ID Registration",updated:"August 2026",intro:"If you send SMS to Kenyan customers — marketing, OTPs, statements or alerts — a registered sender ID is what makes your messages look legitimate and land reliably on Safaricom, Airtel and Telkom. Unregistered or fake sender IDs are increasingly blocked at the network level, so registration is now table stakes, not a nice-to-have.",checklist:["Registered Kenyan business (Certificate of Incorporation)","KRA PIN for the business","Company letterhead for the authorisation letter","Authorised signatory to sign and stamp the request","A sender ID that meets network naming rules (no generic terms)","A clear promotional vs transactional sender ID plan (Safaricom)"],steps:[{step:"1",title:"Choose your sender ID name",description:'Pick a brand-representative alphanumeric ID (up to 11 characters, A–Z, 0–9, no spaces on some networks). Avoid generic words like "INFO" or "BANK" — the networks reject misleading or trademark-infringing names.'},{step:"2",title:"Prepare the authorisation letter",description:"Write a signed, stamped letter on company letterhead authorising MobiWave (or your aggregator) to register the sender ID on your behalf, including your business registration and KRA PIN."},{step:"3",title:"Submit to the networks via CAK framework",description:"The request goes to Safaricom, Airtel and Telkom under the CAK-aligned registration process. A separate transactional and promotional sender ID is typically required by Safaricom."},{step:"4",title:"Wait for network approval",description:"Most sender IDs are approved within 1–3 business days. You will be notified once each network confirms the ID is active for outbound sends."},{step:"5",title:"Start sending from the registered ID",description:"Once approved, use the exact registered casing and spelling. MobiWave enforces the 07:00–19:00 promotional window by default to keep you within CAK advertising rules."},{step:"6",title:"Maintain opt-in compliance",description:"Keep a per-MSISDN opt-in ledger and honour STOP-to-unsubscribe. This supports ODPC data-protection alignment and keeps your sender ID in good standing."}],comparison:{headers:["MobiWave","Africa's Talking","Celcom Africa","Do it yourself"],note:"MobiWave handles CAK sender-ID registration for you at no admin fee. Competitors typically charge KES 7,000 per network; a direct self-submission requires a developer portal account and manual follow-up with each carrier.",rows:[{name:"Registration fee",cells:[{text:"Free, handled for you",highlight:!0},{text:"KES 7,000 / network"},{text:"KES 7,000 / network"},{text:"Free but manual"}]},{name:"Networks covered",cells:[{text:"Safaricom, Airtel, Telkom",highlight:!0},{text:"All three"},{text:"All three"},{text:"You liaise per carrier"}]},{name:"Approval time",cells:[{text:"1–3 business days",highlight:!0},{text:"1–3 business days"},{text:"1–3 business days"},{text:"Variable"}]},{name:"Promotional + transactional IDs",cells:[{text:"Both registered",highlight:!0},{text:"Both"},{text:"Both"},{text:"You request each"}]},{name:"Local support",cells:[{text:"24/7 phone + WhatsApp",highlight:!0},{text:"Developer-only"},{text:"Business hours"},{text:"None"}]}]},faqs:[{question:"Do I need to register a sender ID in Kenya?",answer:"If you send commercial SMS to Kenyan subscribers, yes. The networks increasingly block unregistered or impersonating sender IDs, so registration is required for reliable delivery on Safaricom, Airtel and Telkom."},{question:"How much does sender ID registration cost?",answer:"MobiWave registers your sender ID across all three networks during onboarding at no extra admin fee. Some aggregators charge around KES 7,000 per network — we do not."},{question:"How long does approval take?",answer:"Most sender IDs are approved within 1–3 business days once the signed authorisation letter and business documents are submitted."},{question:"What documents do I need?",answer:"Your Certificate of Incorporation, KRA PIN, and a signed, stamped authorisation letter on company letterhead. A trademark certificate helps if the ID matches a registered brand."},{question:"Can my sender ID be rejected?",answer:'Yes — generic terms (e.g. "BANK", "INFO"), misleading names, or trademark infringements are rejected. Choose a clear brand-representative ID to avoid delays.'},{question:"Why do I need separate promotional and transactional IDs?",answer:"Safaricom requires distinct sender IDs for promotional and transactional traffic so it can apply the correct rules (e.g. the 07:00–19:00 promotional window). MobiWave registers both for you."},{question:"Does sender ID registration cover WhatsApp or email?",answer:"No. Sender ID registration is for SMS only. WhatsApp uses the official Business API with Meta verification, and email uses SPF/DKIM/DMARC on your domain — separate processes."},{question:"Is a sender ID the same as a shortcode?",answer:'No. A sender ID is the outbound "from" name on SMS; a shortcode is a short number customers text to for two-way interaction. Many businesses use both.'},{question:"What are the rules for sending promotional SMS?",answer:"Kenya’s CAK framework restricts promotional SMS to roughly 07:00–19:00 and requires opt-in consent. MobiWave enforces the window by default and maintains your opt-in ledger for ODPC alignment."},{question:"Can MobiWave register my sender ID for me?",answer:"Yes. MobiWave handles CAK-aligned sender ID registration with all three networks during onboarding at no extra admin fee — you provide the documents and we manage the submission and follow-up."}],relatedRoutes:[{label:"Bulk SMS",href:"/services/bulk-sms"},{label:"SMS Shortcodes & Sender IDs",href:"/services/shortcodes"},{label:"SMS Surveys",href:"/services/sms-surveys"}]})}export{l as SenderIdRegistrationGuide};
